+    // 2 local butterfly stages
+    {
+      const float a0 = data[0], a1 = data[1], a2 = data[2], a3 = data[3];
+      data[0] = a0 + a1;
+      data[1] = a0 - a1;
+      data[2] = a2 + a3;
+      data[3] = a2 - a3;
+    }
+    {
+      const float a0 = data[0], a1 = data[1], a2 = data[2], a3 = data[3];
+      data[0] = a0 + a2;
+      data[1] = a1 + a3;
+      data[2] = a0 - a2;
+      data[3] = a1 - a3;
+    }
+    // 5 cross-lane shfl_xor butterfly stages
+#pragma unroll
+    for (uint32_t mask = 1; mask < kWarpThreads; mask <<= 1) {
+#pragma unroll
+      for (int i = 0; i < kVecSize; ++i) {
+        const float other = __shfl_xor_sync(0xFFFFFFFFu, data[i], mask, kWarpThreads);
+        data[i] = (lane_id & mask) ? (other - data[i]) : (data[i] + other);
+      }
+    }
+    const float kHadamardScale = math::rsqrt(static_cast<float>(kHeadDim));
+#pragma unroll
+    for (int i = 0; i < kVecSize; ++i)
+      data[i] *= kHadamardScale;
+  }
+
+  // ---- Part 4: int8 per-head symmetric quantization ----
+  {
+    // Step 4a: compute per-head abs_max
+    float local_max = math::abs(data[0]);
+#pragma unroll
+    for (int i = 1; i < kVecSize; ++i) {
+      local_max = math::max(local_max, math::abs(data[i]));
+    }
+    const auto abs_max = warp::reduce_max(local_max);
+
+    // Step 4b: scale = abs_max / 127, clip to avoid division by zero
+    const auto scale = fmaxf(1e-4f, abs_max) / kInt8Max;
+    const auto inv_scale = 1.0f / scale;
+
+    // Step 4c: quantize to int8 with round-to-nearest and clamp
+    OutStorage result;
+#pragma unroll
+    for (int i = 0; i < kVecSize; ++i) {
+      float qval = data[i] * inv_scale;
+      qval = rintf(qval);
+      qval = fmaxf(qval, -kInt8Max);
+      qval = fminf(qval, kInt8Max);
+      result[i] = static_cast<int8_t>(qval);
+    }
+
+    // Step 4d: write int8 output -- each lane writes 4 int8 values
+    auto out_row = static_cast<int8_t*>(params.q_int8) + work_id * kHeadDim;
+    result.store(out_row, lane_id);
+
+    // Step 4e: lane 0 writes weights_out; scale is internal only (same as fp8 version).
+    if (lane_id == 0) {
+      params.weights_out[work_id] = weight_val * params.weight_scale * scale;
+    }
+  }
+}
