+            smem_up[stage][tid][i] = __float2bfloat16_rn(0.0f);
+          }
+        }
+      }
+    } else {
+      if constexpr (!kIsFullBlock) {
+#pragma unroll
+        for (int i = 0; i < kElemPerThread; ++i) {
+          smem_gate[stage][tid][i] = __float2bfloat16_rn(0.0f);
+          smem_up[stage][tid][i] = __float2bfloat16_rn(0.0f);
+        }
