+  int issue_stage = 0;
+  int t_load = token_block_id;
+#pragma unroll
+  for (int s = 0; s < kStages - 1; ++s) {
+    issue_token_load(issue_stage, t_load);
+    issue_stage = (issue_stage + 1) % kStages;
+    t_load += token_stride;
+  }
+
+  int compute_stage = 0;
+  for (int t = token_block_id; t < n_tokens; t += token_stride) {
+    issue_token_load(issue_stage, t_load);
+    issue_stage = (issue_stage + 1) % kStages;
+    t_load += token_stride;
+
+    cp_async_wait_group<kStages - 1>();
