+    float local_absmax;
+    float fp32_prods[kPairsPerThread][2];
+    if constexpr (kApplySwigluLimit) {
+      local_absmax = 0.0f;
+#pragma unroll
+      for (int i = 0; i < kPairsPerThread; ++i) {
