+      }
+#pragma unroll
+      for (int i = 0; i < kPairsPerThread; ++i) {
+        q[2 * i] = __bfloat162float(__low2bfloat16(q_pairs_scaled[i]));
+        q[2 * i + 1] = __bfloat162float(__high2bfloat16(q_pairs_scaled[i]));
