+  const float g0 = __bfloat162float(__low2bfloat16(gate));
+  const float g1 = __bfloat162float(__high2bfloat16(gate));
+  const float silu0 = g0 * __ppu_sgmdf(g0);
+  const float silu1 = g1 * __ppu_sgmdf(g1);
