+    float local_max = 0.0f;
+    float results[kValuesPerThread];
+#pragma unroll
+    for (uint32_t i = 0; i < kValuesPerThread / 2; ++i) {
+      const auto [x, y] = situ_and_mul<false>(gate_vec[i], up_vec[i], beta, inv_beta, linear_beta, inv_linear_beta);
