+        results[0] * inv_scale,
+        results[1] * inv_scale,
+        results[2] * inv_scale,
+        results[3] * inv_scale,
+        results[4] * inv_scale,
+        results[5] * inv_scale,
+        results[6] * inv_scale,
+        results[7] * inv_scale);
